package com.propbuy.web;
import com.propbuy.repo.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/favorites") public class FavoriteController { final JdbcTemplate db; final UserRepository users; final ListingRepository listings; FavoriteController(JdbcTemplate d,UserRepository u,ListingRepository l){db=d;users=u;listings=l;}
 @PostMapping("/{listingId}") @PreAuthorize("hasRole('BUYER')") Map<String,Object> add(@PathVariable Long listingId,Authentication a){var user=users.findByEmailIgnoreCase(a.getName()).orElseThrow();listings.findById(listingId).orElseThrow();db.update("INSERT IGNORE INTO favorites(user_id,listing_id) VALUES (?,?)",user.getId(),listingId);return Map.of("saved",true,"listingId",listingId);}
 @DeleteMapping("/{listingId}") @PreAuthorize("hasRole('BUYER')") Map<String,Object> remove(@PathVariable Long listingId,Authentication a){var user=users.findByEmailIgnoreCase(a.getName()).orElseThrow();db.update("DELETE FROM favorites WHERE user_id=? AND listing_id=?",user.getId(),listingId);return Map.of("saved",false,"listingId",listingId);}
 @GetMapping @PreAuthorize("hasRole('BUYER')") List<Map<String,Object>> mine(Authentication a){var user=users.findByEmailIgnoreCase(a.getName()).orElseThrow();return db.queryForList("SELECT f.listing_id, f.created_at, l.asking_price, p.title, p.city FROM favorites f JOIN resale_listings l ON l.id=f.listing_id JOIN properties p ON p.id=l.property_id WHERE f.user_id=? ORDER BY f.created_at DESC",user.getId());}
}
